package vitor.tinelli.data;

import java.time.Year;

public class Data {
    private int mes;
    private int dia;
    private int ano;

    public Data(int dia, int mes, int ano) {
        setAno(ano);
        setMes(mes);
        setDia(dia);
    }

    // Getters
    public int getMes() {
        return mes;
    }

    public int getDia() {
        return dia;
    }

    public int getAno() {
        return ano;
    }

    // Setters com validação
    public void setMes(int mes) {
        if (mes < 1 || mes > 12) {
            throw new IllegalArgumentException("Mês deve estar entre 1 e 12. Valor informado: " + mes);
        }
        this.mes = mes;
    }

    public void setAno(int ano) {
        this.ano = ano;
    }

    public void setDia(int dia) {
        int diasNoMes = getDiasNoMes(mes, ano);
        if (dia < 1 || dia > diasNoMes) {
            throw new IllegalArgumentException("Dia deve estar entre 1 e " + diasNoMes + " para o mês " + mes + ". Valor informado: " + dia);
        }
        this.dia = dia;
    }

    // Método auxiliar para calcular dias no mês
    private int getDiasNoMes(int mes, int ano) {
        switch (mes) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                return 31;
            case 4: case 6: case 9: case 11:
                return 30;
            case 2:
                return Year.isLeap(ano) ? 29 : 28;
            default:
                return 0;
        }
    }

    public void displayData() {
        System.out.printf("%02d/%02d/%d%n", dia, mes, ano);
    }
}

package vitor.tinelli.data;

public class DataTeste {
    public static void main(String[] args) {
        System.out.println("=== Teste da Classe Data ===\n");

        // Teste 1: Datas válidas
        System.out.println("1. Testando datas válidas:");
        try {
            Data data1 = new Data(15, 8, 2025);
            System.out.print("Data 1: ");
            data1.displayData();

            Data data2 = new Data(29, 2, 2024); // Ano bissexto
            System.out.print("Data 2 (ano bissexto): ");
            data2.displayData();

            Data data3 = new Data(31, 12, 2023);
            System.out.print("Data 3: ");
            data3.displayData();

        } catch (IllegalArgumentException e) {
            System.out.println("Erro inesperado: " + e.getMessage());
        }

        System.out.println("\n2. Testando datas inválidas:");

        // Teste 2: Mês inválido
        System.out.println("\n2.1. Testando mês inválido (13):");
        try {
            Data dataInvalida1 = new Data(15, 13, 2025);
        } catch (IllegalArgumentException e) {
            System.out.println("Erro capturado: " + e.getMessage());
        }

        // Teste 3: Dia inválido em mês com 30 dias
        System.out.println("\n2.2. Testando dia 31 em abril (mês com 30 dias):");
        try {
            Data dataInvalida2 = new Data(31, 4, 2025);
        } catch (IllegalArgumentException e) {
            System.out.println("Erro capturado: " + e.getMessage());
        }

        // Teste 4: 29 de fevereiro em ano não bissexto
        System.out.println("\n2.3. Testando 29 de fevereiro em ano não bissexto (2023):");
        try {
            Data dataInvalida3 = new Data(29, 2, 2023);
        } catch (IllegalArgumentException e) {
            System.out.println("Erro capturado: " + e.getMessage());
        }

        // Teste 5: Dia inválido (0)
        System.out.println("\n2.4. Testando dia inválido (0):");
        try {
            Data dataInvalida4 = new Data(0, 1, 2025);
        } catch (IllegalArgumentException e) {
            System.out.println("Erro capturado: " + e.getMessage());
        }

        // Teste 6: Testando setters
        System.out.println("\n3. Testando getters e setters:");
        try {
            Data data4 = new Data(1, 1, 2025);
            System.out.print("Data inicial: ");
            data4.displayData();

            data4.setDia(25);
            data4.setMes(12);
            data4.setAno(2024);
            System.out.print("Após mudanças: ");
            data4.displayData();

            System.out.println("Dia: " + data4.getDia());
            System.out.println("Mês: " + data4.getMes());
            System.out.println("Ano: " + data4.getAno());

        } catch (IllegalArgumentException e) {
            System.out.println("Erro: " + e.getMessage());
        }

        System.out.println("\n=== Fim dos Testes ===");
    }
}
